mk(){ n=$1; sd=${2:-new}; o=cnt; [ $sd = deny ] && o=cntd; mkdir -p art/$n/$o; cp art/$n/$sd/art.h art/$n/$o/; { echo '#include "../../../cnt_pre.h"'; awk '/static inline size_t rx_reqrun/{r=1} r&&/memchr\(/{gsub(/memchr\(/,"cmemchr(")} r&&/rx_w[248]\(subject \+ cand\)/{sub(/if \(/,"if (++k_cmp, ")} r&&/^}/{r=0} {print}' art/$n/$sd/art.c | sed -E 's/if \(rx_reqrun\(subject, subject_length, search_from\) >= subject_length\) return 0;/k_gate++; if (rx_reqrun(subject, subject_length, search_from) >= subject_length) return 0; k_pass++;/'; } > art/$n/$o/art.c; gcc-16 -O2 -Iart/$n/$o -o art/$n/$o/run drv.c art/$n/$o/art.c 2>&1 | grep -i error; }
run(){ n=$1; s=$2; o=${3:-cnt}; printf '%-14s %-10s ' $n $s; art/$n/$o/run t subj/$s.bin 1 2>&1 >/dev/null | tail -1; }
